INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT138-S3-Q5$batch02$, 138, 3, 5, $batch02$Flaw$batch02$, $batch02$Editorialist: Many professional musicians claim that unauthorized music-sharing services, which allow listeners to obtain music for free, rob musicians of royalties. While it is true that musicians are deprived of royalties they deserve, music-sharing services are not to blame since record companies, publishers, managers, and other intermediaries take an inequitably large cut of the revenues from music sales.$batch02$, $batch02$The reasoning in the editorialist’s argument is most vulnerable to criticism on the grounds that the argument$batch02$, $batch02$A$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=138 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT138-S3-Q5$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$concludes that one party is not blameworthy merely because another party is blameworthy$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT138-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$attempts to promote a particular behavior simply by showing that many people engage in that behavior$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT138-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$attacks a position based solely on the character of the people who hold that position$batch02$, $batch02$Not Ad Hominem$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT138-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$tries to show that a position is false simply by pointing out an undesirable consequence of holding that position$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT138-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$treats a necessary condition for blameworthiness as though it were a sufficient condition for blameworthiness$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT138-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT138-S3-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$Music-sharing services are not to blame for musicians' lost royalties.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Intermediaries take an unfairly large cut of music revenue.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Grant that the intermediaries take too much. Can the sharing services still be to blame? Of course. Two roommates can both have eaten the cake. Blame is not a single prize that goes to one party. The editorialist finds one culprit and acquits the other without examining it.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the answer saying one party's blame does not clear another.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT138-S3-Q5$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The only reason given for clearing the sharing services is that the intermediaries are at fault. Both can contribute to musicians' losses, so blaming one does not excuse the other.$batch02$), ($batch02$B$batch02$, $batch02$The editorialist does not promote any behavior by citing its popularity.$batch02$), ($batch02$C$batch02$, $batch02$The editorialist does not attack the musicians' character. He grants that they are deprived of royalties.$batch02$), ($batch02$D$batch02$, $batch02$No undesirable consequence of the musicians' view is used against it.$batch02$), ($batch02$E$batch02$, $batch02$There is no conditional rule about blameworthiness here to scramble. The error is treating blame as if only one party could have it.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT138-S3-Q5$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
